export default function f({ events, previous }) {
  const list = Array.isArray(events) ? events : [];
  const i = previous?.i ?? 0;
  const e = list[i];
  if (!e?.messageId) return { state: { i }, more: false, messageId: "." };
  return { state: { i: i + 1 }, more: true, messageId: e.messageId };
}

