export default function f({ messageId, threadId, from, subject, body }) {
  if (!messageId || !threadId) throw Error("Missing message identity");
  const snippet = String(body || "").slice(0, 2000),
    fStr = String(from || ""),
    sStr = String(subject || "");
  return {
    messageId,
    messageIds: [messageId],
    threadId,
    from: fStr,
    subject: sStr,
    snippet,
    body: { messageId, threadId, from: fStr, subject: sStr, snippet },
  };
}

