export default async function calendar({ calendarId, timeZone }, ctx) {
  if (!calendarId || calendarId.includes("YOUR_")) throw Error("Configure calendar");
  Intl.DateTimeFormat("en", { timeZone });
  const now = new Date(),
    start = new Date(now.getTime() - 86400000),
    end = new Date(now);
  end.setUTCMonth(end.getUTCMonth() + 1);
  let token = null,
    seen = new Set(),
    events = [];
  do {
    const page = await ctx.actions.call("googlecalendar.list_events", {
      calendarId,
      timeMin: start.toISOString(),
      timeMax: end.toISOString(),
      timeZone,
      singleEvents: true,
      maxResults: 250,
      ...(token ? { pageToken: token } : {}),
    });
    if (!Array.isArray(page.items)) throw Error("Invalid calendar page");
    events.push(
      ...page.items.map((e) => ({
        start: e.start,
        end: e.end,
        status: e.status,
        transparency: e.transparency,
      })),
    );
    token = page.nextPageToken ?? null;
    if (token && seen.has(token)) throw Error("Repeated calendar cursor");
    if (token) seen.add(token);
  } while (token);
  return { events: JSON.stringify(events), now: now.toISOString(), timeZone };
}

