export default async function reserve({ body, acknowledge, resolution }, ctx) {
  if (!body?.messageId || !body?.threadId) throw Error("Missing message identity");
  const key = "appointment-reply:" + body.messageId,
    old = await ctx.state.get(key);
  if (old?.status === "done") return { key, send: false };
  if (old?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending reply " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { key, send: false };
    }
  }
  await ctx.state.set(key, { status: "pending" });
  return { key, send: true };
}

